// String goldens: the launcher has exactly two command forms. The POSIX form
// uses /bin/sh; the Windows form is the same wrapper in .cmd
// syntax (CRLF, rem comments, %* passthrough).
func TestShimTextGolden(t *testing.T) {
	posix := shimTextFor("darwin", "/opt/rolling-memory/bin/rolling-memory")
	wantPosix := "#!/bin/sh\n" +
		"# Rolling-Memory launcher (generated by `rolling-memory install`).\n" +
		"# Absolute path on purpose: harnesses often spawn MCP servers and hooks with a cropped PATH.\n" +
		"exec \"/opt/rolling-memory/bin/rolling-memory\" \"$@\"\n"
	if posix != wantPosix {
		t.Fatalf("POSIX shim mismatch:\n--- got ---\n%q\n--- want ---\n%q", posix, wantPosix)
	}

	windows := shimTextFor("windows", `C:\Tools\rolling-memory\rolling-memory.exe`)
	wantWindows := "@echo off\r\n" +
		"rem Rolling-Memory launcher (generated by `rolling-memory install`).\r\n" +
		"rem Absolute path on purpose: harnesses often spawn MCP servers and hooks with a cropped PATH.\r\n" +
		"\"C:\\Tools\\rolling-memory\\rolling-memory.exe\" %*\r\n"
	if windows != wantWindows {
		t.Fatalf("Windows shim mismatch:\n--- got ---\n%q\n--- want ---\n%q", windows, wantWindows)
	}
}

func TestShimTextHost(t *testing.T) {
	if ShimText() != shimTextFor(runtime.GOOS, executablePath()) {
		t.Fatalf("ShimText does not use the running platform / executable")
	}
	if !strings.Contains(ShimText(), "Rolling-Memory launcher") {
		t.Fatalf("shim lost the ownership marker")
	}
}

func TestDefaultShimPath(t *testing.T) {
	dataHome := t.TempDir()
	t.Setenv("XDG_DATA_HOME", dataHome)
	home := t.TempDir()
	path := DefaultShimPath(home)
	if !strings.HasPrefix(path, dataHome) {
		t.Fatalf("shim path = %q, want prefix %q", path, dataHome)
	}
	if filepath.Base(path) != shimNameFor(runtime.GOOS) {
		t.Fatalf("shim name = %q", filepath.Base(path))
	}
	if got := defaultShimPathFor("windows", home); filepath.Base(got) != "rolling-memory.cmd" {
		t.Fatalf("windows shim name = %q", filepath.Base(got))
	}
}

func TestShlexQuoteGolden(t *testing.T) {
	cases := []struct{ in, want string }{
		{"", "''"},
		{"/opt/rolling-memory/bin/rolling-memory.sh", "/opt/rolling-memory/bin/rolling-memory.sh"},
		{"rolling-memory", "rolling-memory"},
		{"/opt/my tools/rolling-memory", "'/opt/my tools/rolling-memory'"},
		{`C:\Tools\rolling-memory.cmd`, `'C:\Tools\rolling-memory.cmd'`},
		{"it's", `'it'"'"'s'`},
		{"用户/工具", "'用户/工具'"},
	}
	for _, testCase := range cases {
		if got := shlexQuote(testCase.in); got != testCase.want {
			t.Fatalf("shlexQuote(%q) = %q, want %q", testCase.in, got, testCase.want)
		}
	}
}

func TestHookCommandsGolden(t *testing.T) {
	options := DefaultInstallOptions("/home/user", "/work")
	options.Binary = "/opt/rm/rolling-memory"
	commands := hookCommands(options)
	if len(commands) != 1 {
		t.Fatalf("commands = %d, want 1 (only the per-prompt recall nudge is wired)", len(commands))
	}
	if commands[0].Command != "/opt/rm/rolling-memory hook recall --json" || commands[0].Timeout != 15 {
		t.Fatalf("command[0] = %q timeout %d", commands[0].Command, commands[0].Timeout)
	}

	spaced := DefaultInstallOptions("/home/user", "/work")
	spaced.Binary = "/opt/my tools/rolling-memory"
	if got := hookCommands(spaced)[0].Command; got != "'/opt/my tools/rolling-memory' hook recall --json" {
		t.Fatalf("spaced command = %q", got)
	}

	windows := DefaultInstallOptions(`C:\Users\User`, `C:\Work`)
	windows.Binary = `C:\Tools\rolling-memory.cmd`
	if got := hookCommands(windows)[0].Command; got != `'C:\Tools\rolling-memory.cmd' hook recall --json` {
		t.Fatalf("windows command = %q", got)
	}
}

func TestEnsureBinaryShimLifecycle(t *testing.T) {
	fx := newFixture(t)
	options := fx.options()
	assertNoFailures(t, Install(fx.registry(), options))
	shim := DefaultShimPath(fx.home)
	if !fileExists(shim) {
		t.Fatalf("shim missing")
	}
	second := Install(fx.registry(), options)
	if action := actionsFor(second, "*", "binary")[0]; action.Status != StatusUnchanged {
		t.Fatalf("second shim status = %q", action.Status)
	}
}

func TestEnsureBinaryConflictsOnForeignShim(t *testing.T) {
	fx := newFixture(t)
	shim := DefaultShimPath(fx.home)
	if err := os.MkdirAll(filepath.Dir(shim), 0o755); err != nil {
		t.Fatalf("mkdir shim dir: %v", err)
	}
	if err := os.WriteFile(shim, []byte("#!/bin/sh\necho foreign\n"), 0o755); err != nil {
		t.Fatalf("write foreign shim: %v", err)
	}
	report := Install(fx.registry(), fx.options())
	actions := actionsFor(report, "*", "binary")
	if len(actions) != 1 || actions[0].Status != StatusConflict {
		t.Fatalf("binary actions = %#v", actions)
	}
	if content := readFile(t, shim); content != "#!/bin/sh\necho foreign\n" {
		t.Fatalf("foreign shim overwritten: %q", content)
	}
}

func TestShimOwnershipChecks(t *testing.T) {
	if !hasShimSuffixFor("/opt/rolling-memory/bin/rolling-memory.sh", "darwin") {
		t.Fatalf("POSIX shim path not recognised")
	}
	if !hasShimSuffixFor(`C:\Tools\rolling-memory.cmd`, "windows") {
		t.Fatalf("Windows shim path not recognised")
	}
	if hasShimSuffixFor(`C:\Tools\rolling-memory.cmd`, "darwin") {
		t.Fatalf("Windows shim recognised on darwin")
	}

	options := DefaultInstallOptions("/home/user", "/work")
	options.Binary = "/opt/rm/rolling-memory"
	if !entryIsOurs(map[string]any{"command": "rmem", "args": []any{"mcp"}}, options) {
		t.Fatalf("bare rmem entry not ours")
	}
	if !entryIsOurs(map[string]any{"command": "/opt/rm/rolling-memory", "args": []any{"mcp"}}, options) {
		t.Fatalf("resolved entry not ours")
	}
	if entryIsOurs(map[string]any{"command": "/usr/bin/other", "args": []any{"mcp"}}, options) {
		t.Fatalf("foreign entry claimed as ours")
	}
	if entryIsOurs(map[string]any{"command": "/opt/rm/rolling-memory", "args": []any{"serve"}}, options) {
		t.Fatalf("entry without mcp arg claimed as ours")
	}
	if !hookIsOurs("/opt/rm/rolling-memory hook start --json", options) {
		t.Fatalf("hook not ours")
	}
	if hookIsOurs("guard.sh hook start --json", options) {
		t.Fatalf("foreign hook claimed as ours")
	}
	if !regionIsOurs("command = 'rolling_memory'", options) || regionIsOurs("command = 'other'", options) {
		t.Fatalf("region ownership mismatch")
	}
}

func TestPortableShimHostAnchor(t *testing.T) {
	posix := PortableShimTextFor("darwin", "/Volumes/USB/rolling-memory/bin/rolling-memory", "/Volumes/USB/rolling-memory")
	if !strings.Contains(posix, "Rolling-Memory launcher") {
		t.Fatalf("portable POSIX shim missing ownership marker")
	}
	if !strings.Contains(posix, "/Volumes/*") || !strings.Contains(posix, "ROLLING_MEMORY_PORTABLE") {
		t.Fatalf("portable POSIX shim missing mount-drift scan: %s", posix)
	}

	win := PortableShimTextFor("windows", `E:\rolling-memory\bin\rolling-memory.exe`, `E:\rolling-memory`)
	if !strings.Contains(win, "Rolling-Memory launcher") || !strings.Contains(win, "for %%D in") {
		t.Fatalf("portable Windows shim missing drive-letter scan: %s", win)
	}
}
